    @Test
    public void test_url_builder_init() {
        // Arrange
        String url = "https://example.com/path?query=value#anchor";
        URLBuilder urlBuilder = new UrlBuilder(new URI("https", null, "example.com", 443, "/path", "?query=value", "#anchor"));
        // Act
        urlBuilder.build();
        // Assert
        assertEquals(url, urlBuilder.u.toString());
    }

    @Test
    public void test_url_builder_append_key_val() {
        // Arrange
        String key = "key";
        String value = "value";
        UrlBuilder urlBuilder = new UrlBuilder(new URI("https://example.com/path?query=value#anchor"));
        String expected = "key=value&anchor#anchor";
        urlBuilder.appendKeyVal(UrlBuilder.KeyVal.of(key, value));
        // Act
        String actual = urlBuilder.u.toString();
        // Assert
        assertEquals(expected, actual);
    }

